import { Button } from '@refy-design/web';
import { Modal } from '@refy-design/web';
import { Timeline } from '@refy-design/web';
import type { TimelineMilestone } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
function sampleArtwork(color = '#c7d9ce', width = 1200, height = 800) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 1200 800"><rect width="1200" height="800" fill="${color}"/><rect x="240" y="110" width="720" height="580" rx="16" fill="#fafbf8"/><rect x="300" y="170" width="280" height="340" rx="8" fill="#254e3e"/><circle cx="440" cy="305" r="86" fill="${color}"/><path d="M354 430h172" stroke="#fafbf8" stroke-width="8"/><path d="M630 194h256m-256 40h182m-182 80h256m-256 32h256m-256 32h210m-210 132h220M300 570h586m-586 32h380" stroke="#91a69a" stroke-width="12" stroke-linecap="round"/></svg>`;
  return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(svg)}`;
}
const items: TimelineMilestone[] = [
  {
    id: 'discovery',
    timestamp: '2026-08-05T12:00:00-03:00',
    title: 'The start of the journey',
    description: "We got the team together and set the project's first goals.",
    media: (
      <>
        <img src={sampleArtwork()} alt="First visual proposal" width={80} height={54} />
        <img
          src={sampleArtwork('#cbd4e4')}
          alt="Second visual proposal"
          width={80}
          height={54}
        />
      </>
    ),
    status: 'completed',
  },
  {
    id: 'prototype',
    timestamp: '2026-09-12T12:00:00-03:00',
    title: 'First version validated',
    description:
      'The prototype was tested and the key decisions were shared with the team.',
    status: 'completed',
  },
  {
    id: 'delivery',
    timestamp: '2026-10-23T12:00:00-03:00',
    title: 'Preparing the launch',
    description:
      'We reviewed the details and organized the materials for the next step.',
    status: 'current',
  },
  {
    id: 'launch',
    timestamp: '2026-11-10T12:00:00-03:00',
    title: 'Launch',
    description:
      'A new stage to track results and learn from the people who use the product.',
    status: 'upcoming',
  },
];
export function Example() {
  const args: Pick<
    ComponentProps<typeof Timeline>,
    'items' | 'title' | 'description'
  > = {
    items,
    title: 'From idea to launch',
    description: 'The moments that built this journey.',
  };
  const [selected, setSelected] = useState<TimelineMilestone | null>(null);
  return (
    <>
      <Timeline
        {...args}
        items={args.items.map((item) => ({
          ...item,
          action: (
            <Button size="sm" variant="ghost" onClick={() => setSelected(item)}>
              View milestone
            </Button>
          ),
        }))}
      />
      <Modal
        open={!!selected}
        onClose={() => setSelected(null)}
        title={selected?.title ?? 'Milestone details'}
      >
        {selected?.description}
      </Modal>
    </>
  );
}

